SELECT r.artifact_id, r.artifact_ref, r.owner_id, r.owner_ref, r.kind, r.lifecycle, r.version, r.report_id, r.title, r.source_artifact_id, r.base_artifact_ref, r.policy_ref, r.document_version, r.report_document_json, r.report_spec_json, r.compile_state_json, r.report_fill_json, r.report_print_json, r.saved_view_overlay_json, r.metadata_json, r.created_at, r.updated_at FROM (SELECT t.* FROM  (SELECT 0 AS should_delete, `artifact_id`, `artifact_ref`, `owner_id`, COALESCE(`owner_ref`, '') AS `owner_ref`, `kind`, `lifecycle`, `version`, COALESCE(`report_id`, '') AS `report_id`, COALESCE(`title`, '') AS `title`, COALESCE(`source_artifact_id`, '') AS `source_artifact_id`, COALESCE(`base_artifact_ref`, '') AS `base_artifact_ref`, COALESCE(`policy_ref`, '') AS `policy_ref`, `document_version`, `report_document_json`, `report_spec_json`, `compile_state_json`, `report_fill_json`, `report_print_json`, `saved_view_overlay_json`, `metadata_json`, `created_at`, `updated_at` FROM report_shared_artifact)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)